.isabee-transcript{box-sizing:border-box;min-height:260mm;padding:3mm 1mm;font-family:Arial,sans-serif;font-size:8px;line-height:1.15;display:flex;flex-direction:column}
.isabee-official{display:grid;grid-template-columns:1fr 22mm 1fr;align-items:start;gap:4mm;text-align:center;font-family:'Times New Roman',serif;font-size:8px;line-height:1.18}.isabee-official>div{min-width:0}.isabee-official .isabee-faculty{display:flex;align-items:flex-start;justify-content:center;padding-top:1mm}.isabee-faculty img{display:block;width:21mm;height:21mm;object-fit:contain;margin:0 auto}.isabee-school{display:grid;grid-template-columns:18% 64% 18%;align-items:center;text-align:center;font-family:Arial,sans-serif;font-size:8px;line-height:1.2;margin:5mm 0 3mm}.isabee-school-title{font-weight:bold}.isabee-school-title strong{font-size:14px}.isabee-mark img{max-width:19mm;max-height:19mm;object-fit:contain}
.isabee-transcript h1{text-align:center;font-size:12px;margin:2mm 0 3mm;color:#111}.isabee-identity{display:grid;grid-template-columns:1fr 1fr;gap:4mm;font-size:9px;line-height:1.45;margin-bottom:2mm}.isabee-transcript table{width:100%;border-collapse:collapse;table-layout:fixed;margin:0;font-size:7px}.isabee-transcript th,.isabee-transcript td{border:1px solid #222;padding:2px;line-height:1.08;vertical-align:middle}.isabee-transcript th{background:#fff}.isabee-left{text-align:left!important}.isabee-ue{width:9%}.isabee-code{width:8%}.isabee-course{width:32%}.isabee-type{width:5%}.isabee-mark{width:7%}.isabee-mgp{width:6%}.isabee-grade{width:6%}.isabee-credit,.isabee-earned{width:7%}.isabee-year{width:8%}.isabee-semester{width:5%}.isabee-total th,.isabee-total td{font-weight:bold;border-top:2px solid #222;background:#f3f3f3}
.isabee-semester-row th{background:#fff!important;text-align:left;font-weight:bold;border:0;border-bottom:1px solid #222;padding-top:4px}.isabee-ue-row th,.isabee-ue-row td{font-weight:bold;background:#f3f3f3!important}.isabee-summary{display:grid;grid-template-columns:2fr 1fr 1fr;gap:6px;margin-top:auto;padding-top:3mm;font-size:8px;text-align:center}.isabee-summary>div{border:1px solid #777;padding:4px}.isabee-summary>.isabee-grading{text-align:left;font-size:7px}.isabee-grading>div{display:grid;grid-template-columns:12% 1fr 24%;border-top:1px solid #aaa;padding:1px}.isabee-issued{text-align:right;margin-top:2mm;font-size:9px}.isabee-signatures{display:flex;justify-content:space-between;margin:2mm 4mm 0;min-height:20mm}.isabee-signatures strong{width:45%;text-align:center}.isabee-note{text-align:left;font-size:7px;margin:2mm 0 0;border-top:1px solid #777;padding-top:2mm}
@media print{.modele-isabee.document-releve .preview{display:none}.isabee-transcript{min-height:260mm;break-after:page;page-break-after:always}.isabee-transcript:last-of-type{break-after:auto;page-break-after:auto}.isabee-transcript tr{break-inside:avoid}}
.paper-a3 .isabee-transcript{min-height:380mm;font-size:11px}.paper-a3 .isabee-official,.paper-a3 .isabee-identity,.paper-a3 .isabee-transcript table{font-size:10px}.paper-a3 .isabee-school strong{font-size:20px}.paper-a3 .isabee-transcript h1{font-size:16px}
